<script lang="ts">
  import type {
    PokePelagoAssignCandidateSnapshot,
    PokePelagoUiSnapshot,
  } from '../bus/snapshots.js';
  import { portalToBody } from '../lib/portalToBody.ts';
  import type { PokePelagoIslandId } from '../lib/pokePelagoLogic.ts';
  import { game } from '../../gameManager.ts';
  import { hideGameTooltip, showGameTooltip } from '../ui/scheduleTooltipHelpers.ts';

  interface Props {
    islandId: PokePelagoIslandId;
    islandName: string;
    candidates: PokePelagoAssignCandidateSnapshot[];
    ui: PokePelagoUiSnapshot;
    label?: string;
    customClass?: string;
    children?: import('svelte').Snippet;
  }

  let {
    islandId,
    islandName,
    candidates,
    ui,
    label = '',
    customClass = '',
    children,
  }: Props = $props();

  let open = $state(false);
  let searchQuery = $state('');
  let anchorEl: HTMLElement | undefined = $state();
  let popoverEl: HTMLDivElement | undefined = $state();
  let anchorRect = $state<DOMRect | null>(null);

  const POPOVER_GAP = 8;
  const POPOVER_MIN_WIDTH = 240;

  let filteredCandidates = $derived.by(() => {
    const q = searchQuery.trim().toLowerCase();
    const base = candidates.map((c) => {
      if (islandId !== 'evelup' || !c.atMaxLevel) return c;
      if (c.disabled) return c;
      return {
        ...c,
        disabled: true,
        disabledReason: ui.evelupMaxLevel,
      };
    });
    if (!q) return base;
    return base.filter((c) => c.name.toLowerCase().includes(q));
  });

  function openPicker() {
    if (anchorEl) anchorRect = anchorEl.getBoundingClientRect();
    searchQuery = '';
    open = true;
  }

  function closePicker() {
    open = false;
  }

  function togglePicker() {
    if (open) closePicker();
    else openPicker();
  }

  function positionPopover(node: HTMLDivElement, rect: DOMRect) {
    const height = node.offsetHeight || 120;
    const width = Math.max(POPOVER_MIN_WIDTH, node.offsetWidth || 260);
    let left = rect.left + rect.width / 2 - width / 2;
    let top = rect.bottom + POPOVER_GAP;
    if (left + width > window.innerWidth - 8) left = window.innerWidth - width - 8;
    if (left < 8) left = 8;
    if (top + height > window.innerHeight - 8) {
      top = rect.top - height - POPOVER_GAP;
    }
    if (top < 8) top = 8;
    node.style.left = `${left}px`;
    node.style.top = `${top}px`;
    node.style.minWidth = `${POPOVER_MIN_WIDTH}px`;
  }

  function formatLevel(level: number): string {
    const tpl = ui.levelAbbrev || 'Lv.{level}';
    if (tpl.includes('{level}')) return tpl.replaceAll('{level}', String(level));
    const trimmed = tpl.replace(/\s+$/, '');
    return `${trimmed}${level}`;
  }

  function islandNameForId(id: NonNullable<PokePelagoAssignCandidateSnapshot['assignedIslandId']>): string {
    if (id === 'abeens') return ui.nameAbeens;
    if (id === 'aphun') return ui.nameAphun;
    return ui.nameEvelup;
  }

  function pick(candidate: PokePelagoAssignCandidateSnapshot) {
    const blockedForEvelup = islandId === 'evelup' && candidate.atMaxLevel;
    if (candidate.disabled || blockedForEvelup) return;
    if (candidate.assignedIslandId && candidate.assignedIslandId !== islandId) {
      const island = islandNameForId(candidate.assignedIslandId);
      const msg = ui.reassignConfirm.replace('{island}', island);
      if (typeof window !== 'undefined' && !window.confirm(msg)) return;
    }
    game?.assignPokePelago?.(islandId, candidate.uid, 'storage', candidate.storageIndex);
    closePicker();
  }

  $effect(() => {
    if (!open) return;
    const rect = anchorRect;
    const node = popoverEl;
    if (!node || !rect) return;
    positionPopover(node, rect);
    const onResize = () => positionPopover(node, rect);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  });

  $effect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closePicker();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  });

  // Close on outside pointerdown without preventDefault so Claim / Claim-all still receive the click.
  $effect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target;
      if (!(target instanceof Node)) return;
      if (popoverEl?.contains(target) || anchorEl?.contains(target)) return;
      closePicker();
    };
    document.addEventListener('pointerdown', onPointerDown, true);
    return () => document.removeEventListener('pointerdown', onPointerDown, true);
  });
</script>

<div class="poke-pelago-picker-anchor {customClass}" bind:this={anchorEl}>
  {#if children}
    <!-- svelte-ignore a11y_click_events_have_key_events -->
    <div
      class="poke-pelago-picker-custom-trigger"
      role="button"
      tabindex="0"
      onclick={togglePicker}
      onkeydown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          togglePicker();
        }
      }}
      aria-expanded={open}
      aria-haspopup="dialog"
    >
      {@render children()}
    </div>
  {:else}
    <button
      type="button"
      class="miltank-farm-btn miltank-farm-btn--feed poke-pelago-assign-btn"
      class:is-open={open}
      onclick={togglePicker}
      aria-expanded={open}
      aria-haspopup="dialog"
    >
      {label}
    </button>
  {/if}
</div>

{#if open}
  <div class="poke-pelago-popover-portal" use:portalToBody>
    <div
      class="poke-pelago-popover"
      bind:this={popoverEl}
      role="dialog"
      tabindex="-1"
      aria-label="{ui.pickTitle} — {islandName}"
      onkeydown={(e) => e.stopPropagation()}
    >
      <div class="poke-pelago-popover-header">
        <span class="poke-pelago-popover-title">{ui.pickTitle}</span>
        <span class="poke-pelago-popover-subtitle">{islandName}</span>
        <button type="button" class="poke-pelago-popover-close" onclick={closePicker} aria-label={ui.pickerClose}
          >×</button
        >
      </div>

      {#if candidates.length > 0}
        <input
          type="search"
          class="poke-pelago-picker-search"
          placeholder={ui.pickerSearch}
          bind:value={searchQuery}
          autocomplete="off"
        />
      {/if}

      {#if candidates.length === 0}
        <p class="poke-pelago-popover-empty">{ui.noCandidates}</p>
      {:else if filteredCandidates.length === 0}
        <p class="poke-pelago-popover-empty">{ui.pickerEmptyFilter}</p>
      {:else}
        <div class="poke-pelago-popover-grid" role="listbox">
          {#each filteredCandidates as candidate (candidate.uid)}
            <button
              type="button"
              class="poke-pelago-tile"
              class:poke-pelago-tile--elsewhere={!!candidate.assignedIslandId && !candidate.disabled}
              role="option"
              aria-selected="false"
              aria-disabled={candidate.disabled}
              disabled={candidate.disabled}
              onmouseenter={(e) => showGameTooltip(e, candidate.name, candidate.disabledReason ?? '')}
              onmouseleave={hideGameTooltip}
              onfocus={(e) => showGameTooltip(e, candidate.name, candidate.disabledReason ?? '')}
              onblur={hideGameTooltip}
              onclick={() => pick(candidate)}
            >
              <img
                class="poke-pelago-tile-sprite"
                src={candidate.spriteUrl}
                alt=""
                width="40"
                height="40"
              />
              <span class="poke-pelago-tile-name">{candidate.name}</span>
              <span class="poke-pelago-tile-meta">{formatLevel(candidate.level)}</span>
              {#if candidate.disabledReason}
                <span class="poke-pelago-tile-hint">{candidate.disabledReason}</span>
              {/if}
            </button>
          {/each}
        </div>
      {/if}
    </div>
  </div>
{/if}

<style>
